import com.sun.net.httpserver.*;import java.io.IOException;import java.time.LocalDate;import java.util.*;import model.*;
public final class CaseApiHandler implements HttpHandler{private final CaseDao cases;private final OfficerDao officers;private final SessionManager sessions;private final AuditLogDao audit=new AuditLogDao();public CaseApiHandler(CaseDao c,OfficerDao o,SessionManager s){cases=c;officers=o;sessions=s;}
public void handle(HttpExchange e)throws IOException{try{if(e.getRequestMethod().equals("GET")){StringBuilder j=new StringBuilder("[");for(CaseRecord c:cases.findAll()){if(j.length()>1)j.append(',');j.append("{\"caseId\":\"").append(q(c.getCaseId())).append("\",\"title\":\"").append(q(c.getTitle())).append("\",\"description\":\"").append(q(c.getDescription())).append("\",\"severity\":\"").append(c.getSeverity()).append("\",\"status\":\"").append(c.getStatus()).append("\",\"opened\":\"").append(c.getDateOpened()).append("\",\"priority\":").append(c.calculatePriorityScore()).append(",\"officer\":\"").append(q(c.getAssignedOfficer()==null?"Unassigned":c.getAssignedOfficer().getName())).append("\"}");}HttpUtil.text(e,200,j.append(']').toString(),"application/json");return;}if(sessions.get(HttpUtil.cookie(e,"CCECS_SESSION")).orElseThrow().getRole()==Role.FIELD_AGENT){HttpUtil.text(e,403,"{\"error\":\"Field Agents cannot modify cases\"}","application/json");return;}Map<String,String> f=HttpUtil.form(e);Officer o=f.containsKey("officerId")?officers.findById(f.get("officerId")):officers.leastLoaded();if(o==null)throw new IllegalArgumentException();CaseRecord c=new CaseRecord(req(f,"caseId"),req(f,"title"),req(f,"description"),Severity.valueOf(req(f,"severity")));c.setStatus(CaseStatus.valueOf(f.getOrDefault("status","OPEN")));if(f.containsKey("opened"))c.setDateOpened(LocalDate.parse(f.get("opened")));c.assignOfficer(o);UserSession u=sessions.get(HttpUtil.cookie(e,"CCECS_SESSION")).orElse(null);String uid=u==null?null:u.getUserId();if(e.getRequestMethod().equals("PUT")){cases.update(c,o.getId());audit.record(uid,"CASE_UPDATED","CASE",c.getCaseId(),"CASE_ID="+c.getCaseId()+"; title="+c.getTitle()+"; officer="+o.getId());HttpUtil.text(e,200,"{\"message\":\"Case updated\"}","application/json");}else{cases.save(c,o.getId());audit.record(uid,"CASE_CREATED","CASE",c.getCaseId(),"CASE_ID="+c.getCaseId()+"; title="+c.getTitle()+"; officer="+o.getId());HttpUtil.text(e,201,"{\"message\":\"Case created\"}","application/json");}}catch(Exception x){HttpUtil.text(e,400,"{\"error\":\"Unable to save case\"}","application/json");}}
private String req(Map<String,String>f,String k){String v=f.get(k);if(v==null||v.trim().isEmpty())throw new IllegalArgumentException();return v.trim();}private String q(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"");}}
